; timi.asm -- chapter 17: the BIOS's routine, with a hook of the program's own
; generated by gen17.py
        INCLUDE "msx.inc"
        OUTPUT "timi.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
ticks   EQU RESULTS             ; frames tick has counted
; A program that does nothing but wait for the next frame, in mode 1: the
; BIOS's routine takes every interrupt, and calls tick through H.TIMI.
init:   di
        ld sp, SYS_AREA
        im 1
        ld hl, 0
        ld (ticks), hl
        ld hl, tick             ; H.TIMI: JP tick, written with the
        ld (H_TIMI + 1), hl     ; interrupts off, so that no interrupt
        ld a, $C3               ; can find half a jump there
        ld (H_TIMI), a
        in a, (VDP_CTRL)        ; no signal left over from before
        ei
main:   halt                    ; the BIOS's routine runs, and comes back here
        jr main

; tick: called by the BIOS through H.TIMI every frame, with A = the status it
;       read. The BIOS has saved every register: tick may use any.
tick:   ld hl, (ticks)
        inc hl
        ld (ticks), hl
        ret
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
